const settings = $('Settings').first().json;
const out = String($input.first().json.output || '');
const pick = (key) => {
  const m = out.match(new RegExp('^\\s*' + key + '\\s*:\\s*(.+)$', 'im'));
  return m ? m[1].trim().replace(/^["'“]+|["'”]+$/g, '') : '';
};
const topic = pick('TOPIC');
if (!topic) throw new Error('Topic Picker returned no TOPIC line: ' + out.slice(0, 200));
return [{ json: { ...settings, topic, angle: pick('ANGLE'), audience: pick('AUDIENCE') || settings.audience } }];

