const raw = String($input.first().json.output || '').trim();

const between = (start, end) => {
  const s = raw.indexOf(start);
  if (s === -1) return '';
  const from = s + start.length;
  const e = raw.indexOf(end, from);
  return (e === -1 ? raw.slice(from) : raw.slice(from, e)).trim();
};

let post = between('===POST===', '===SOURCES===');
if (!post) post = between('===POST===', '===END===');
if (!post) post = raw.replace(/^TOPIC:.*\n/im, '').replace(/^(here('|’)?s|here is)[^\n]*:\s*\n+/i, ''); // fallback: model ignored the format
const sources = between('===SOURCES===', '===END===');
const topic = ((raw.match(/^TOPIC:\s*(.+)$/im) || [])[1] || '').trim();

post = post
  .replace(/^```[a-z]*\s*|\s*```$/g, '')
  .replace(/^["“”]+|["“”]+$/g, '')
  .replace(/\*\*/g, '')
  .replace(/\s*[—–]\s*/g, ' - ')
  .replace(/\n{3,}/g, '\n\n')
  .trim();

const words = post.split(/\s+/).filter(Boolean).length;
const problems = [];
if (words < 60) problems.push('post too short (' + words + ' words)');
if (post.length > 2900) problems.push('post too long (' + post.length + ' chars)');
if (!/#\w+/.test(post)) problems.push('no hashtags');
if (/\[(source|topic|company|name|link|insert)[^\]]*\]|<token>|lorem ipsum/i.test(post)) problems.push('placeholder text found');
if (problems.length) throw new Error('Post validation failed: ' + problems.join('; '));

return [{ json: { post, topic, sources, words, chars: post.length } }];

const p = String($input.first().json.output || '')
  .replace(/^```[a-z]*\s*|\s*```$/g, '')
  .replace(/^["“”]+|["“”]+$/g, '')
  .trim();
if (p.length < 40) throw new Error('Image prompt is empty or too short');
return [{ json: { image_prompt: p } }];

